        else if (next_level == 2'd3)
            next_dfr = 1'b0;
    end

    always_ff @(posedge clk) begin
        if (reset) begin
            level <= 2'd0;
            dfr   <= 1'b1;
        end else begin
            level <= next_level;
            dfr   <= next_dfr;
        end
    end

    always_comb begin
        fr2 = 1'b0;
        fr1 = 1'b0;
